const n5 = node({type: "n8n-nodes-base.httpRequest", version: 4.3, config: {name: "Fetch Source", position: [1120, 272], parameters: {"method": "GET", "url": expr("{{ $json.source_url }}"), "sendHeaders": true, "headerParameters": {"parameters": [{"name": "User-Agent", "value": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"}, {"name": "Accept-Language", "value": "ja,en;q=0.8"}]}, "options": {"timeout": 30000, "response": {"response": {"responseFormat": "text"}}, "batching": {"batch": {"batchSize": 1, "batchInterval": 2000}}}}, retryOnFail: true, maxTries: 3, waitBetweenTries: 4000, onError: "continueRegularOutput"}, output: [{}]});
const n6 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Re-check Source", position: [1344, 272], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Re-check Source: re-fetch the HelloWork detail page and compare with what WF01 stored. Deterministic. Nothing is trusted from WF01 without re-proof.\nconst cfg = $('Config').first().json;\nconst norm = (s) => String(s || '').replace(/[\\s　]+/g, '');\nconst nowJ = new Date(Date.now() + 9 * 3600 * 1000);\nconst todayUTC = Date.UTC(nowJ.getUTCFullYear(), nowJ.getUTCMonth(), nowJ.getUTCDate());\nconst md2date = (arr, mode) => { if (!arr || arr.length < 2) return null; const m = Number(arr[0]); const d = Number(arr[1]); if (!m || !d) return null; const y = nowJ.getUTCFullYear(); let t = Date.UTC(y, m - 1, d); if (mode === 'posted' && t > todayUTC + 2 * 86400000) t = Date.UTC(y - 1, m - 1, d); if (mode === 'expiry' && t < todayUTC - 200 * 86400000) t = Date.UTC(y + 1, m - 1, d); return t; };\nconst toText = (h) => String(h || '').replace(/<script[\\s\\S]*?<\\/script>/gi, '').replace(/<style[\\s\\S]*?<\\/style>/gi, '').replace(/<br\\s*\\/?>/gi, '\\n').replace(/<\\/(p|div|tr|li|h\\d|table|dt|dd)>/gi, '\\n').replace(/<[^>]+>/g, '\\n').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\\n[ \\t　]*(?=\\n)/g, '').replace(/\\n{2,}/g, '\\n').trim();\nconst OVERSEAS_OK = [/海外(在住)?(の方|者)?(から|在住).{0,8}(応募|可|歓迎|OK|ＯＫ)/, /(国外|海外)在住.{0,4}(可|OK|ＯＫ|歓迎)/, /来日前.{0,12}(応募|面接|内定|選考)/, /(入国前|渡日前).{0,12}(応募|面接|内定|選考)/, /(海外|来日前).{0,20}オンライン面接|オンライン面接.{0,20}(海外|来日前)/];\nconst DOMESTIC = [/(海外|国外)在住.{0,4}(不可|不可能|ＮＧ|NG)/, /国内(に)?在住(の方|者)?(のみ|限)/, /日本(国)?内に(在住|居住).{0,10}(方|者|必須)/, /在留カード.{0,12}(必須|をお持ちの方のみ)/];\nconst hit = (arr, t) => { for (const r of arr) { const m = t.match(r); if (m) return m[0].slice(0, 80); } return ''; };\nconst out = [];\nconst inputs = $input.all();\nfor (let k = 0; k < inputs.length; k++) {\n  const it = inputs[k];\n  let job = {};\n  try { job = $('Flatten Queue').itemMatching(k).json; } catch (e) { job = {}; }\n  const err = it.json && it.json.error;\n  const html = (it.json && it.json.data) || '';\n  const errors = [];\n  const rc = { source_state: 'OK', host_ok: /^https:\\/\\/(www\\.)?hellowork\\.careers\\//.test(job.source_url || '') || /^https:\\/\\/www\\.hellowork\\.mhlw\\.go\\.jp\\//.test(job.source_url || ''), conflicts: [] };\n  let text = '';\n  if (err) { const m = String(err.message || err.description || err); rc.source_state = /404|410|not found/i.test(m) ? 'GONE' : 'UNREACHABLE'; rc.detail = m.slice(0, 200); errors.push({ stage: 'source_fetch', type: rc.source_state, msg: m.slice(0, 200) }); }\n  else if (typeof html !== 'string' || html.length < 3000) { rc.source_state = /Fatal error|detail\\.php/.test(String(html)) ? 'BROKEN' : 'UNREACHABLE'; rc.detail = 'response too short (' + String(html || '').length + ')'; errors.push({ stage: 'source_fetch', type: rc.source_state, msg: rc.detail }); }\n  else {\n    const full = toText(html);\n    const start = full.indexOf('の募集内容、仕事概要');\n    if (/(掲載を終了|受付を終了|募集を終了|求人は終了|この求人は.{0,6}(終了|締め切)|ページが見つかりません)/.test(full.slice(0, 4000)) && start < 0) rc.source_state = 'CLOSED_ON_SOURCE';\n    const body = (start >= 0 ? full.slice(Math.max(0, start - 80)) : full).slice(0, 12000);\n    text = body;\n    const lines = body.split('\\n').map((s) => s.trim()).filter((s) => s.length);\n    const after = (label) => { const i = lines.indexOf(label); return i >= 0 && i + 1 < lines.length ? lines[i + 1] : ''; };\n    const hdr = lines.find((l) => /の募集内容、仕事概要$/.test(l));\n    rc.page_company = hdr ? hdr.replace(/の募集内容、仕事概要$/, '').trim() : '';\n    const wi = lines.indexOf('勤務地');\n    rc.page_address = wi >= 0 ? lines.slice(wi + 1, wi + 4).filter((l) => !/^〒/.test(l) && !/^就業場所|^マイカー|^転勤/.test(l))[0] || '' : '';\n    rc.haken = after('派遣・請負等'); rc.wage_text = after('賃金'); rc.wage_form = after('賃金形態'); rc.annual_text = after('年間休日');\n    const wnum = String(rc.wage_text).replace(/,/g, '').match(/([0-9]{4,7})/);\n    rc.wage_min = wnum ? Number(wnum[1]) : null;\n    const hm = String(rc.wage_form).replace(/,/g, '').match(/時給([0-9]{3,5})/);\n    rc.hourly = hm ? Number(hm[1]) : null;\n    rc.annual = Number(String(rc.annual_text).replace(/[^0-9]/g, '')) || null;\n    const posted = md2date((full.match(/受理日：([0-9]{1,2})月([0-9]{1,2})日/) || []).slice(1, 3), 'posted');\n    const expiry = md2date((full.match(/有効期限：([0-9]{1,2})月([0-9]{1,2})日/) || []).slice(1, 3), 'expiry');\n    rc.days_left = expiry ? Math.round((expiry - todayUTC) / 86400000) : null;\n    rc.posted_age_days = posted ? Math.round((todayUTC - posted) / 86400000) : null;\n    rc.page_corp = (body.match(/法人番号[^0-9]{0,6}([0-9]{13})/) || [])[1] || '';\n    const jn = String(job.job_number || '').replace(/-/g, '');\n    rc.source_job_match = !!jn && full.replace(/-/g, '').indexOf(jn) >= 0;\n    rc.ssw_in_text = body.indexOf('特定技能') >= 0;\n    rc.ssw_quote_ok = !!job.ssw_quote && job.ssw_quote.length >= 4 && norm(body).indexOf(norm(job.ssw_quote)) >= 0;\n    rc.overseas_hit = hit(OVERSEAS_OK, body); rc.domestic_hit = hit(DOMESTIC, body);\n    // conflicts vs WF01-stored facts\n    if (job.monthly_min && rc.wage_min && !job.hourly && Math.abs(job.monthly_min - rc.wage_min) > Math.max(1000, job.monthly_min * 0.01)) rc.conflicts.push('salary: stored ' + job.monthly_min + ' vs source ' + rc.wage_min);\n    if (job.hourly && rc.hourly && job.hourly !== rc.hourly) rc.conflicts.push('hourly: stored ' + job.hourly + ' vs source ' + rc.hourly);\n    if (job.annual_holidays && rc.annual && job.annual_holidays !== rc.annual) rc.conflicts.push('annual holidays: stored ' + job.annual_holidays + ' vs source ' + rc.annual);\n    if (job.wf01_corp && rc.page_corp && job.wf01_corp !== rc.page_corp) rc.conflicts.push('法人番号: stored ' + job.wf01_corp + ' vs source ' + rc.page_corp);\n    const core = (s) => String(s || '').normalize('NFKC').replace(/株式会社|有限会社|合同会社|\\(株\\)|\\(有\\)|[\\s　]/g, '');\n    if (job.company && rc.page_company && core(job.company) !== core(rc.page_company)) rc.conflicts.push('company: stored ' + job.company + ' vs source ' + rc.page_company);\n  }\n  const base = Object.assign({}, job, { rc, detail_text: text, errors });\n  base.dup_query_body = job.company\n    ? { filter: { property: 'Company', rich_text: { equals: job.company } }, page_size: 25 }\n    : { filter: { property: 'Job Number', rich_text: { equals: job.job_number } }, page_size: 25 };\n  out.push({ json: base });\n}\nreturn out;\n"}, notes: "Re-fetch HelloWork page: freshness, source/job match, SSW quote, wage/holiday conflicts, dispatch field, overseas wording."}, output: [{}]});
const n7 = node({type: "n8n-nodes-base.httpRequest", version: 4.3, config: {name: "Dup Query", position: [1568, 272], parameters: {"method": "POST", "url": expr("{{ \"https://api.notion.com/v1/data_sources/\" + $(\"Config\").first().json.notion_job_ds_id + \"/query\" }}"), "authentication": "genericCredentialType", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "Notion-Version", "value": "2025-09-03"}]}, "sendBody": true, "contentType": "json", "specifyBody": "json", "jsonBody": expr("{{ JSON.stringify($json.dup_query_body) }}"), "options": {"timeout": 30000, "batching": {"batch": {"batchSize": 1, "batchInterval": 400}}}, "genericAuthType": "httpHeaderAuth"}, retryOnFail: true, maxTries: 3, waitBetweenTries: 2000, onError: "continueRegularOutput", notes: "Auth: Header Auth credential (Authorization: Bearer <Notion integration secret>) so our Notion-Version 2025-09-03 header is not overridden by the built-in Notion credential.", credentials: {httpHeaderAuth: newCredential("Notion Bearer (Header Auth)")}}, output: [{}]});
const n8 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Duplicate Check", position: [1792, 272], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Duplicate / Conflict check against Master Job DB (same company). Notion is the source of truth.\nconst norm = (s) => String(s || '').normalize('NFKC').replace(/[\\s　]+/g, '');\nconst plain = (a) => (a || []).map((x) => x.plain_text || '').join('');\nconst out = [];\nconst inputs = $input.all();\nfor (let k = 0; k < inputs.length; k++) {\n  const it = inputs[k];\n  let job = {};\n  try { job = $('Re-check Source').itemMatching(k).json; } catch (e) { job = {}; }\n  const errors = (job.errors || []).slice();\n  const res = it.json && Array.isArray(it.json.results) ? it.json.results : null;\n  let dup = { state: 'Unknown', note: '' };\n  if (!res || (it.json && it.json.error)) { dup.note = 'duplicate query failed'; errors.push({ stage: 'dup_check', type: 'notion_error', msg: String((it.json && it.json.error && it.json.error.message) || 'bad response').slice(0, 200) }); }\n  else {\n    dup = { state: 'Unique', note: '' };\n    const advanced = ['VERIFIED', 'CONTENT_READY', 'IMAGE_READY', 'APPROVED', 'PUBLISHED', 'UPDATED'];\n    for (const o of res) {\n      if (o.id === job.page_id) continue;\n      const P = o.properties || {};\n      const ojn = plain((P['Job Number'] || {}).rich_text).trim();\n      const ot = plain((P['Job Title'] || {}).title);\n      const oc = plain((P['City'] || {}).rich_text); const os = P['Status'] && P['Status'].select ? P['Status'].select.name : '';\n      const earlier = String(o.created_time) <= String(job.created_time) || advanced.indexOf(os) >= 0;\n      if (ojn && ojn === job.job_number && earlier) { dup = { state: 'Duplicate', note: 'same Job Number as ' + o.id + ' (' + os + ')' }; break; }\n      if (norm(ot) === norm(job.title) && norm(oc) === norm(job.city) && earlier && dup.state !== 'Duplicate') dup = { state: 'Possible Duplicate', note: 'same company+title+city as ' + o.id + ' (' + os + ', job ' + ojn + ')' };\n    }\n  }\n  out.push({ json: Object.assign({}, job, { dup, errors, dup_query_body: undefined }) });\n}\nreturn out;\n"}}, output: [{}]});
const n9 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Build Registry Request", position: [2016, 272], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Build Registry Request: company verification is its own process (not dependent on 法人番号 being printed in the posting).\nconst cfg = $('Config').first().json;\nconst corpOK = (c) => { if (!/^[0-9]{13}$/.test(c || '')) return false; const d = c.split('').map(Number); let s = 0; for (let n = 1; n <= 12; n++) { const p = d[13 - n]; s += p * (n % 2 === 1 ? 1 : 2); } return (9 - (s % 9)) === d[0]; };\nconst base = String(cfg.gbiz_base || 'https://info.gbiz.go.jp/hojin').replace(/\\/$/, '');\nconst out = [];\nfor (const it of $input.all()) {\n  const j = it.json; const rc = j.rc || {};\n  const given = [rc.page_corp, j.wf01_corp].filter((c) => corpOK(c))[0] || '';\n  const name = String(rc.page_company || j.company || '').normalize('NFKC').replace(/[\\s　]+/g, '');\n  let mode = 'NONE'; let url = base + '/v1/hojin?name=' + encodeURIComponent('__none__') + '&limit=1';\n  if (given) { mode = 'BY_NUMBER'; url = base + '/v1/hojin/' + given; }\n  else if (name) { mode = 'BY_NAME'; url = base + '/v1/hojin?name=' + encodeURIComponent(name) + '&limit=20'; }\n  out.push({ json: Object.assign({}, j, { gbiz: { mode, url, given_number: given } }) });\n}\nreturn out;\n"}, notes: "Company verification is independent of the posting: by 法人番号 if known, else by company name."}, output: [{}]});
const n10 = node({type: "n8n-nodes-base.httpRequest", version: 4.3, config: {name: "Registry Lookup", position: [2240, 272], parameters: {"method": "GET", "url": expr("{{ $json.gbiz.url }}"), "authentication": "genericCredentialType", "genericAuthType": "httpHeaderAuth", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "Accept", "value": "application/json"}]}, "options": {"timeout": 30000, "batching": {"batch": {"batchSize": 1, "batchInterval": 1100}}}}, retryOnFail: true, maxTries: 3, waitBetweenTries: 3000, onError: "continueRegularOutput", notes: "gBizINFO REST API. Credential: Header Auth, name X-hojinInfo-api-token, value = your token.", credentials: {httpHeaderAuth: newCredential("gBizINFO API Token")}}, output: [{}]});
const n11 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Company Score", position: [2464, 272], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Company Score: match registry record vs posting on 法人番号 + name + address (+ active status). Deterministic, facts only.\nconst cfg = $('Config').first().json;\nconst th = Number(cfg.company_threshold) || 90;\nconst N = (s) => String(s || '').normalize('NFKC').replace(/[\\s　]+/g, '');\nconst core = (s) => N(s).replace(/株式会社|有限会社|合同会社|合資会社|合名会社|一般社団法人|一般財団法人|公益社団法人|公益財団法人|社会福祉法人|医療法人社団|医療法人財団|医療法人|農事組合法人|協同組合|\\(株\\)|\\(有\\)|\\(同\\)|\\(社\\)|\\(医\\)|\\(福\\)/g, '').replace(/[()（）]/g, '');\nconst corpOK = (c) => { if (!/^[0-9]{13}$/.test(c || '')) return false; const d = c.split('').map(Number); let s = 0; for (let n = 1; n <= 12; n++) { const p = d[13 - n]; s += p * (n % 2 === 1 ? 1 : 2); } return (9 - (s % 9)) === d[0]; };\nconst nameMatch = (a, b) => { const x = core(a); const y = core(b); if (!x || !y) return 'NONE'; if (x === y) return 'EXACT'; const [s, l] = x.length <= y.length ? [x, y] : [y, x]; return (l.indexOf(s) >= 0 && s.length / l.length >= 0.7) ? 'PARTIAL' : 'NONE'; };\nconst addrMatch = (loc, j) => { const L = N(loc); const pref = N(j.prefecture); const city = N(j.city); const rcA = N((j.rc && j.rc.page_address) || ''); const A = N(j.address); let lvl = 'NONE';\n  if (pref && L.indexOf(pref) >= 0) lvl = 'PREF';\n  if (!pref && rcA) { const m = rcA.match(/^(.{2,3}?[都道府県])/); if (m && L.indexOf(m[1]) >= 0) lvl = 'PREF'; }\n  const cityTxt = city || (rcA.replace(/^.{2,3}?[都道府県]/, '').match(/^(.{1,6}?[市区町村郡])/) || [])[1] || '';\n  if (cityTxt && L.indexOf(cityTxt) >= 0 && (lvl === 'PREF' || !pref)) lvl = 'CITY';\n  return lvl; };\nconst out = [];\nconst inputs = $input.all();\nfor (let k = 0; k < inputs.length; k++) {\n  const it = inputs[k];\n  let j = {};\n  try { j = $('Build Registry Request').itemMatching(k).json; } catch (e) { j = {}; }\n  const errors = (j.errors || []).slice();\n  const g = j.gbiz || {}; const rc = j.rc || {};\n  const co = { verdict: 'REVIEW', score: 0, parts: { number: 0, name: 0, address: 0, active: 0, direct: 0 }, number: '', number_source: 'NONE', number_confirmed: false, registry_name: '', registry_location: '', active: null, notes: [], conflict: '' };\n  const err = it.json && it.json.error;\n  const arr = it.json && (it.json['hojin-infos'] || it.json.hojin_infos || it.json.hojinInfos);\n  const msg = err ? String(err.message || err.description || err) : '';\n  if (g.mode === 'NONE') { co.verdict = 'REVIEW'; co.notes.push('no company name or 法人番号 to search'); }\n  else if (err) {\n    if (/404|not found/i.test(msg)) { co.notes.push('registry: not found (' + g.mode + ')'); if (g.mode === 'BY_NUMBER') co.conflict = '法人番号 ' + g.given_number + ' not found in registry'; }\n    else { co.verdict = 'REGISTRY_UNAVAILABLE'; co.notes.push('registry request failed: ' + msg.slice(0, 120)); errors.push({ stage: 'registry', type: /401|403|unauthor|forbidden/i.test(msg) ? 'auth' : 'request', msg: msg.slice(0, 200) }); }\n  } else if (!Array.isArray(arr)) { co.verdict = 'REGISTRY_UNAVAILABLE'; co.notes.push('registry: unexpected response shape'); errors.push({ stage: 'registry', type: 'shape', msg: 'no hojin-infos array' }); }\n  else {\n    const postName = rc.page_company || j.company;\n    let pick = null;\n    if (g.mode === 'BY_NUMBER') { pick = arr.filter((x) => x.corporate_number === g.given_number)[0] || null; if (!pick) co.notes.push('registry returned no matching record for ' + g.given_number); }\n    else {\n      const cands = arr.filter((x) => nameMatch(x.name, postName) === 'EXACT' && addrMatch(x.location, j) === 'CITY');\n      if (cands.length === 1) pick = cands[0];\n      else if (cands.length > 1) co.notes.push('ambiguous: ' + cands.length + ' registry records match name+city');\n      else { const loose = arr.filter((x) => nameMatch(x.name, postName) !== 'NONE'); co.notes.push('no registry record matches name+city (' + arr.length + ' returned, ' + loose.length + ' loose name hits)'); }\n    }\n    if (pick) {\n      co.registry_name = pick.name || ''; co.registry_location = pick.location || ''; co.number = pick.corporate_number || '';\n      co.number_source = g.mode === 'BY_NUMBER' ? 'POSTING' : 'REGISTRY_DISCOVERED';\n      const nm = nameMatch(pick.name, postName); const am = addrMatch(pick.location, j);\n      co.parts.number = corpOK(co.number) ? 35 : 0; co.number_confirmed = co.parts.number === 35;\n      co.parts.name = nm === 'EXACT' ? 25 : nm === 'PARTIAL' ? 12 : 0;\n      co.parts.address = am === 'CITY' ? 20 : am === 'PREF' ? 8 : 0;\n      const closed = !!pick.close_date || /閉鎖|解散|清算|合併|廃止/.test(String(pick.status || '') + String(pick.close_cause || ''));\n      co.active = !closed; co.parts.active = closed ? 0 : 10;\n      if (nm === 'NONE') co.conflict = '法人番号 ' + co.number + ' belongs to 「' + co.registry_name + '」 but posting says 「' + postName + '」';\n      if (closed) { co.verdict = 'CLOSED'; co.notes.push('registry marks company closed: ' + String(pick.status || '') + ' ' + String(pick.close_date || '')); }\n    }\n  }\n  const dispatch = (/派遣|請負/.test(rc.haken || '') && !/(ではない|でない|ではありません|なし)/.test(rc.haken || ''));\n  co.parts.direct = (!dispatch && rc.source_state === 'OK') ? 10 : 0;\n  co.score = co.parts.number + co.parts.name + co.parts.address + co.parts.active + co.parts.direct;\n  if (co.verdict !== 'CLOSED' && co.verdict !== 'REGISTRY_UNAVAILABLE') co.verdict = (co.score >= th && !co.conflict) ? 'VERIFIED' : 'REVIEW';\n  co.registry_status = co.verdict;\n  // Per-record manual override ONLY: a human ticked Employer Verified. Affects the registry verdict alone; every other gate still runs. CLOSED is never overridden.\n  if (j.human_employer_verified && (co.verdict === 'REVIEW' || co.verdict === 'REGISTRY_UNAVAILABLE')) { co.verdict = 'MANUAL_VERIFIED'; co.notes.push('Employer Verified ticked by a human in Notion (registry status: ' + co.registry_status + '; NOT registry-verified)'); }\n  const hard = rc.source_state === 'GONE' || rc.source_state === 'CLOSED_ON_SOURCE' || dispatch || (j.dup && j.dup.state === 'Duplicate') || co.verdict === 'CLOSED' || (rc.days_left !== null && rc.days_left !== undefined && rc.days_left < 0) || (rc.source_state === 'OK' && !rc.ssw_in_text);\n  const needs_ai = !hard && !!j.detail_text && rc.source_state === 'OK';\n  out.push({ json: Object.assign({}, j, { co: co, errors, needs_ai: needs_ai ? 'true' : 'false' }) });\n}\nreturn out;\n"}, notes: "法人番号 35 + name 25 + address 20 + active 10 + direct employer 10. >= company_threshold and no conflict => VERIFIED."}, output: [{}]});
const n12 = ifElse({version: 2.2, config: {name: "Needs AI?", position: [2688, 272], parameters: {"conditions": {"options": {"caseSensitive": true, "leftValue": "", "typeValidation": "strict", "version": 2}, "conditions": [{"id": "e97112f9-245a-d5c4-38d2-9ac0b1339a24", "leftValue": expr("{{ String($json.needs_ai) }}"), "operator": {"type": "string", "operation": "equals"}, "rightValue": "true"}], "combinator": "and"}}}, output: [{}]});
const n13 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Prepare Verify", position: [2912, 208], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Prepare Verify: AI second opinion on judgement-type checks only. AI may propose; deterministic code verifies every quote and can only DOWNGRADE.\nconst cfg = $('Config').first().json;\nconst SYSTEM = `あなたは求人票の「検証」専用エンジンです。与えられた求人票テキストに書かれていることだけを根拠に判定します。推測・一般知識・補完は禁止。判断できない場合は必ず UNKNOWN / UNVERIFIED にします。\n出力はJSONオブジェクトのみ（前後の説明・コードフェンス禁止）。引用は求人票テキストからの一字一句そのままの抜粋（60字以内）。見つからなければ \"\"。\n判定項目:\n1. employer_is_direct: この求人の雇用主が自社で直接雇用する事業者なら true。派遣・紹介・請負・登録支援機関・協同組合・プラットフォーム運営なら false。不明なら \"UNKNOWN\"。employer_quote に根拠引用。\n2. ssw_recruit_explicit: この求人自体が特定技能外国人を採用対象としていると明記されているなら true。単なる在籍/活躍/社員区分の言及、管理・支援側の仕事なら false。ssw_quote に根拠引用。\n3. role_is_management: 仕事内容が特定技能外国人の「管理・教育・支援・通訳」側の役割なら true、そうでなければ false。\n4. overseas_applicability: 海外在住のまま応募・面接・内定が可能と明記されていれば \"VERIFIED\"、国内在住者のみ/在留カード必須等と明記なら \"DOMESTIC_ONLY\"、明記なしは \"UNVERIFIED\"（ハローワーク求人というだけでは UNVERIFIED）。overseas_quote に根拠引用。\n5. salary_basis_ok: 賃金が残業代・歩合に依存せず基本給で成立していれば true、依存していれば false、不明なら \"UNKNOWN\"。salary_concern に一言。\nスキーマ: {\"employer_is_direct\":\"\",\"employer_quote\":\"\",\"ssw_recruit_explicit\":false,\"ssw_quote\":\"\",\"role_is_management\":false,\"overseas_applicability\":\"\",\"overseas_quote\":\"\",\"salary_basis_ok\":\"\",\"salary_concern\":\"\",\"other_concerns\":[]}`;\nconst out = [];\nfor (const it of $input.all()) {\n  const j = it.json; const co = j.co || {};\n  const user = '求人番号: ' + j.job_number + '\\nサイト表示の会社名: ' + ((j.rc && j.rc.page_company) || j.company) + '\\n登記情報(参考): ' + (co.registry_name || 'なし') + '\\n---求人票本文---\\n' + String(j.detail_text || '').slice(0, 9000);\n  out.push({ json: Object.assign({}, j, { ai_verify_req: { model: cfg.ai_model_verify, max_tokens: 1200, temperature: 0, system: SYSTEM, messages: [{ role: 'user', content: user }] } }) });\n}\nreturn out;\n"}}, output: [{}]});
const n14 = node({type: "n8n-nodes-base.httpRequest", version: 4.3, config: {name: "AI Verify", position: [3136, 208], parameters: {"method": "POST", "url": "https://api.anthropic.com/v1/messages", "authentication": "genericCredentialType", "genericAuthType": "httpTemplatedCustomAuth", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "anthropic-version", "value": "2023-06-01"}, {"name": "content-type", "value": "application/json"}]}, "sendBody": true, "contentType": "json", "specifyBody": "json", "jsonBody": expr("{{ JSON.stringify($json.ai_verify_req) }}"), "options": {"timeout": 90000, "batching": {"batch": {"batchSize": 3, "batchInterval": 1500}}}}, retryOnFail: true, maxTries: 3, waitBetweenTries: 5000, onError: "continueRegularOutput", credentials: {httpTemplatedCustomAuth: newCredential("Anthropic API Key (x-api-key)")}}, output: [{}]});
const n15 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Parse Verify", position: [3360, 208], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Parse Verify: AI output is DATA. Every quote must exist verbatim in the source text; unverified claims are discarded. AI can only downgrade, never upgrade.\nconst parseJson = (t) => { let s = String(t || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim(); const a = s.indexOf('{'); const b = s.lastIndexOf('}'); if (a < 0 || b < a) return null; try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; } };\nconst norm = (s) => String(s || '').normalize('NFKC').replace(/[\\s　]+/g, '');\nconst out = [];\nconst inputs = $input.all();\nfor (let k = 0; k < inputs.length; k++) {\n  const it = inputs[k];\n  let j = {};\n  try { j = $('Prepare Verify').itemMatching(k).json; } catch (e) { j = {}; }\n  const errors = (j.errors || []).slice();\n  const a = parseJson(it.json && it.json.content && it.json.content[0] && it.json.content[0].text);\n  const base = Object.assign({}, j, { ai_verify_req: undefined, errors });\n  if ((it.json && it.json.error) || !a) { errors.push({ stage: 'ai_verify', type: 'ai_error', msg: (it.json && it.json.error ? String(it.json.error.message || it.json.error) : 'unparseable JSON').slice(0, 200) }); out.push({ json: Object.assign(base, { ai: { ok: false } }) }); continue; }\n  const T = norm(j.detail_text);\n  const q = (s) => { const x = norm(s); return x.length >= 4 && T.indexOf(x) >= 0; };\n  const ai = { ok: true, employer: 'UNKNOWN', employer_quote_ok: q(a.employer_quote), ssw_explicit: a.ssw_recruit_explicit === true && q(a.ssw_quote), management: a.role_is_management === true, overseas: 'UNVERIFIED', overseas_quote_ok: q(a.overseas_quote), salary_basis: a.salary_basis_ok === false ? 'FALSE' : a.salary_basis_ok === true ? 'TRUE' : 'UNKNOWN', salary_concern: String(a.salary_concern || '').slice(0, 120), concerns: (Array.isArray(a.other_concerns) ? a.other_concerns : []).slice(0, 3).map((x) => String(x).slice(0, 100)) };\n  ai.employer = a.employer_is_direct === false ? 'FALSE' : a.employer_is_direct === true ? 'TRUE' : 'UNKNOWN';\n  if (a.overseas_applicability === 'DOMESTIC_ONLY' && ai.overseas_quote_ok) ai.overseas = 'DOMESTIC_ONLY';\n  else if (a.overseas_applicability === 'VERIFIED' && ai.overseas_quote_ok) ai.overseas = 'VERIFIED';\n  out.push({ json: Object.assign(base, { ai }) });\n}\nreturn out;\n"}, notes: "Quotes verified verbatim; AI can only downgrade."}, output: [{}]});
