const n31 = node({type: "n8n-nodes-base.code", version: 2, config: {name: "Shape Error Rows", position: [6496, 432], parameters: {"mode": "runOnceForAllItems", "language": "javaScript", "jsCode": "// Shape Error Rows (WF02): stage-level errors + write failures -> shared error log (source = wf02).\nconst cfg = $('Config').first().json;\nconst rows = [];\nfor (const it of $input.all()) {\n  const j = it.json;\n  const key = String(j.job_number || '');\n  (Array.isArray(j.errors) ? j.errors : []).forEach((e) => rows.push({ json: { run_id: cfg.run_id, ts: cfg.run_started, source: 'wf02', stage: String(e.stage || ''), error_type: String(e.type || ''), error_message: String(e.msg || '').slice(0, 300), retry_status: 'next_run', job_key: key } }));\n  if (j._kind === 'qc_row' && j.write_status !== 'OK') rows.push({ json: { run_id: cfg.run_id, ts: cfg.run_started, source: 'wf02', stage: 'notion_write', error_type: String(j.write_status), error_message: String(j.write_reason || '').slice(0, 300), retry_status: j.write_status === 'NOTION_ERROR' ? 'next_run' : 'manual', job_key: key } });\n  if (j._kind === 'company_write' && !/_OK$/.test(String(j.status))) rows.push({ json: { run_id: cfg.run_id, ts: cfg.run_started, source: 'wf02', stage: 'company_db', error_type: String(j.status), error_message: String(j.reason || '').slice(0, 300), retry_status: 'manual', job_key: key } });\n  if (j._kind === 'meta' && j.status === 'QUEUE_ERROR') { /* already in errors[] */ }\n}\nreturn rows;\n"}}, output: [{}]});
